def find_minimal_edit(s_in, s_out):
    """Find the minimal change between two strings"""
    # Simple approach: find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing a substring
            # Try to find what substring needs to be replaced
            # For now, let's assume single character replacement
            return (s_in[i], s_out[i], i)

    # If we got here, one string is prefix of other
    if len(s_in) > len(s_out):
        # Remove extra characters
        return (s_in[min_len:], "", min_len)
    elif len(s_out) > len(s_in):
        # Add missing characters  
        return ("", s_out[min_len:], min_len)
    else:
        return ("", "", -1)  # No change

